mapper.select:
SELECT TNA.*,STA.REALNAME renyuan FROM TBL_NBSJ_AUDITPROGRAM TNA LEFT JOIN TBL_NBSJ_TEMPLETE ntemp ON ntemp.templeteId = TNA.TEMPID LEFT JOIN TBL_NBSJ_AUTHORIZATION auth on TNA.programid = auth.programid LEFT JOIN TBL_NBSJ_TEAMSTAFF te on AUTH.TEAMSTAFFID=TE.ID LEFT JOIN TBL_STAFF sta on TE.STAFFID=STA.STAFFID
1=1
AND TNA.TARGETID = #{proGramEntity.targetId}
AND ntemp.templeteId = #{proGramEntity.tempId}
ORDER BY TNA.TARGETID,TNA.TEMPID
